def append_enrollment(records, sequence, name, age, category):
    if not isinstance(records, list) or any(not isinstance(item, str) for item in records):
        raise TypeError("records must be a list of strings")
    if isinstance(sequence, bool) or not isinstance(sequence, int):
        raise TypeError("sequence must be an integer")
    if sequence <= 0:
        raise ValueError("sequence must be positive")
    if isinstance(age, bool) or not isinstance(age, int):
        raise TypeError("age must be an integer")
    if not 0 <= age <= 130:
        raise ValueError("age is out of range")

    cleaned = []
    for value in (name, category):
        if not isinstance(value, str):
            raise TypeError("text fields must be strings")
        value = value.strip()
        if not value or any(mark in value for mark in ("|", "\r", "\n")):
            raise ValueError("invalid text field")
        cleaned.append(value)

    line = f"{sequence:04d}|{cleaned[0]}|{age}|{cleaned[1]}"
    records = records + [line]
    return records

